    "id": "IXSIPEM-2024-GT02-0434",
    "title": "Utilizando Erros para Promover a Reflexão Crítica e o Diálogo em Aulas de Matemática",
    "authors": [
      "Dr Luciano Feliciano de Lima (Universidade Estadual de Goiás)",
      "Maria Francisca da Cunha (Universidade Estadual de Goiás)"
    ],
    "abstract": "Investiga-se “como o erro no processo de ensino e aprendizagem de matemática pode favorecer o estabelecimento de um diálogo entre os atores da sala de aula?” Utiliza-se uma abordagem qualitativa, baseada em narrativas reflexivas de licenciandos em Matemática, a pesquisa fundamenta-se em teorias freirianas sobre conscientização e diálogo. Para a produção de dados foram desenvolvidas atividades que incluíram a identificação e correção de equações de primeiro grau por meio de exemplos e contraexemplos, ditados matemáticos e análise de vídeos com erros intencionais. Os resultados indicam que essas atividades podem promover a reflexão crítica, colaboração e desenvolvimento metacognitivo, contribuindo para uma formação em que, como futuros professores, possam ser capazes de criar um ambiente educativo inclusivo e emancipatório em suas práticas.",
