    "abstract": "Este trabalho é um fragmento de uma pesquisa de doutorado em andamento, que visa analisar a implementação do Articulação da Formação Profissional Média e Superior (AMS) em uma Escola Técnica do Estado de São Paulo (Etec), em parceria com uma Faculdade de Tecnologia (Fatec), a partir da lente da teoria crítica embasada nos pressupostos do Agir Comunicativo (TAC) de Jürgen Habermas e da Aceleração Social, de Hartmut Rosa. Nesse primeiro momento da pesquisa, procuramos levantar dados, documentos e normativas da legislação que orientam essa implantação com base na reforma do Ensino Médio. O foco principal é analisar as orientações numa abordagem curricular da Matemática, considerando os reflexos do conceito de aceleração social nesse combo de formação (Médio, Técnico e Superior).",
