    "id": "IXSIPEM-2024-GT03-0331",
    "title": "Projeto Folhas de matemática na formação de professores do Paraná",
    "authors": [
      "Edicléia Xavier da Costa (Secretaria Municipal de Educação de São José dos Pinhais)",
      "Elenilton Vieira Godoy (Universidade Federal do Paraná)"
    ],
    "abstract": "O artigo apresenta uma pesquisa empírica sobre o Projeto Folhas de Matemática, uma política da Secretaria de Estado da Educação do Paraná, entre 2003 e 2010. O objetivo foi investigar as contribuições deste na formação de professores e na elaboração de materiais didático-pedagógicos, por meio do Portal Dia a Dia da Educação. Neste apresentamos reflexões baseadas nas narrativas de técnicos pedagógicos, em consultas a documentos orientadores do projeto e em pesquisas relacionadas ao Projeto Folhas. As narrativas foram produzidas segundo os procedimentos metodológicos da História Oral. Com base nas Políticas Públicas como referencial teórico, conclui-se que o Projeto Folhas foi fundamental para a formação e protagonismo dos professores de matemática, promovendo autoria, valorização profissional e avanços na carreira.",
