    "title": "Conhecimentos especializados de professores de Matemática para o ensino de equações diferenciais ordinárias de variáveis separáveis na Engenharia Civil a partir de um problema de Transferência de Calor",
    "authors": [
      "Gabriel Loureiro de Lima (Pontifícia Universidade Católica de São Paulo)",
      "Rieuse Lopes (Universidade Estadual de Montes Claros)"
    ],
    "abstract": "Neste artigo, tendo por base o modelo MTSK, são analisados os conhecimentos especializados que um professor de Matemática precisa desenvolver ou mobilizar para elaborar e implementar um problema objetivando ensinar equações diferenciais ordinárias (EDO) de variáveis separáveis em cursos de Engenharia Civil. Parte-se de um contexto relacionado à Transferência de Calor por condução unidimensional e regime estacionário em uma parede plana. Sob a perspectiva da Análise de Conteúdo, para alcançar o objetivo visado, analisa-se o percurso de construção do problema. Observa-se que muitos dos conhecimentos independem do tipo de EDO, do contexto extramatemático e da habilitação de Engenharia enfocada. Idealmente, deveriam ser construídos e mobilizados por qualquer professor de Matemática que objetiva ensinar EDO na Engenharia.",
