    "id": "IXSIPEM-2024-GT04-0213",
    "title": "Da Integral de Riemann à Integral de Lebesgue: um estudo alicerçado na Pesquisa Baseada em Design",
    "authors": [
      "Ismael Batista Maidana Silvestre (Universidade Franciscana)",
      "Vanilde Bisognin (Universidade Franciscana)"
    ],
    "abstract": "Esse trabalho teve por objetivo investigar como os licenciandos de um curso de Licenciatura em Matemática, que cursam o último ano, compreendem o conceito de Integral de Riemann, suas limitações e a necessidade de um novo conceito, como o da Integral de Lebesgue, tendo como referencial teórico o Pensamento Matemático Avançado (PMA). Como metodologia de pesquisa, utilizamos a Pesquisa Baseada em Design (PBD). Foi proposto e aplicado um produto educacional construído a partir de princípios de design definidos preliminarmente. As análises foram feitas sobre as produções dos estudantes de uma turma de Análise Matemática. Os resultados evidenciaram que os princípios foram validados no decorrer da aplicação e que o produto educacional, contribuiu para a compreensão dos conceitos.",
