    "abstract": "O estudo analisa o cálculo da jornada de trabalho de um cortador de cana-de-açúcar e foi realizado como requisito para conclusão do curso de Licenciatura em Matemática na Universidade de Pernambuco. O trabalho é qualitativo do tipo estudo de caso e adotou como mecanismo para o levantamento dos dados, os registros sobre a experiência desse estudante de graduação como trabalhador do campo e uma entrevista gravada em celular com um trabalhador aposentado com larga vivência nas funções de cortador de cana, cabo e fiscal. Identificou-se a utilização da braça como referência para realizar suas medições, inclusive, reportando-se a outras formas como a quadra e a conta para medir áreas, particionando-a em triângulos e quadriláteros.",
