    "id": "IXSIPEM-2024-GT06-0133",
    "title": "Análise de movimentos epistêmicos realizados na resolução de problemas deestruturas multiplicativas: gestos e toques em tela que revelam modos depensar matematicamente",
    "authors": [
      "Rony Claudio de Oliveira Freitas (Instituto Federal do Espírito Santo)",
      "Renan Oliveira Altoé (Instituto Federal do Espírito Santo)"
    ],
    "abstract": "Este artigo apresenta análises de movimentos epistêmicos realizados por estudantes no processo resolução de problemas de estruturas multiplicativas. De natureza qualitativa, em uma abordagem interpretativa, os dados foram produzidos com quatro estudantes de um 4º ano do Ensino Fundamental – Anos Iniciais. Com base em estudos sobre Resolução de Problemas, Dispositivos Móveis com Toques em Tela e Cognição Corporificada, a interpretação dos movimentos epistêmicos (gestos e toques em tela) realizados pelos estudantes no desenvolvimento da História “O Mistério dos Cubinhos Dobrados”, enquanto investigavam situações matemáticas de multiplicação, ocorreu por meio da Representação Esquemática Multimodal de Análise de Dados (REMAD). As análises mostraram que os gestos e toques em tela figuraram na aprendizagem matemática, relevando ações epistêmicas dos modos de pensar matematicamente.",
