    "id": "IXSIPEM-2024-GT06-0278",
    "title": "Cinema como Meio de Revelação: tecnologia e educação matemática na transposição de problemas de gênero",
    "authors": [
      "Mauricio Rosa (Universidade Federal do Rio Grande do Sul)"
    ],
    "abstract": "Essa pesquisa qualitativa objetiva discutir o Cinema (via streaming [1] ) como meio de revelação de ações, situações, visões, utopias ou encantamentos à educação matemática, de forma a provocar a transposição de problemas de gênero e articular essa transposição com planos de aula de matemática, por parte de um/a professor/a de matemática. Nesse sentido, discutimos a ideia de Tecnologias Digitais como “meios de revelação”, a concepção de já sermos cyborgs e a transposição de problemas, em específico, de gênero. No caso deste estudo, nos debruçamos sobre a análise de uma cena escolhida e a produção de um plano de aula de matemática por parte de um/a professor/a. Encontramos gretas no “CIStema” [2] , de maneira que a transposição de problemas revelados pelo Cinema, permitiram ao sujeito vislumbrar sua responsabilidade social e héxis política sob sustentação matemática, em prol de pessoas trans.",
