    "abstract": "Este trabalho traz um recorte da pesquisa de doutorado da primeira autora que teve como objetivo analisar como um coletivo de alunos-com-mídias compreende conteúdos de Geometria Euclidiana Espacial – GEE no Ensino Superior em tempos de ensino remoto. Metodologicamente, foi adotada a pesquisa qualitativa. A investigação ocorreu online com alunos de Graduação em Matemática, que cursaram a disciplina GEE, no terceiro semestre, na Universidade Estadual Paulista – UNESP/Rio Claro. Além disso, a experiência baseada em design dialogando com as ideias de Lévy e do construto Seres-Humanos-Com-Mídias serviram de aportes para a interpretação e análise dos dados. Os resultados apontam que o desenvolvimento de diversas atividades por um coletivo de estudantes-com-mídias tem potencial para a aprendizagem de conteúdos da GEE, na qual a visualização constitui-se como parte desse processo.",
