    "id": "IXSIPEM-2024-GT06-0191",
    "title": "Produção de vídeos digitais: contribuições para o ensino da Geometria Analítica",
    "authors": [
      "Ma. Sílvia Mourão Meireles (Universidade Cruzeiro do Sul)",
      "Dr. Juliano Schimiguel (Universidade Cruzeiro do Sul)"
    ],
    "abstract": "Os vídeos figuram como elementos indispensáveis para a comunicação no contexto atual e são frequentemente utilizados como fonte de pesquisa para fins educacionais. Nesse sentido, esse estudo apresenta uma investigação realizada com estudantes do terceiro ano do Ensino Médio de uma escola técnica localizada na cidade de São Paulo. Como objetivo buscou investigar possibilidades e limitações da produção de vídeos digitais por estudantes, auxiliadas pelo software Geogebra, no âmbito da Geometria Analítica. Trata-se de uma pesquisa com abordagem qualitativa e quanto aos procedimentos, caracteriza-se como um estudo de caso. A investigação revela que práticas apoiadas na produção de vídeos digitais favorecem a comunicação das ideias matemáticas, oportunizando fundamentalmente o incentivo à pesquisa, autoria e uso crítico das mídias.",
