    "id": "IXSIPEM-2024-GT07-0354",
    "title": "Uma adaptação do Lesson Study no Estágio Supervisionado: indícios da constituição da identidade profissional na Formação Inicial do professor de Matemática",
    "authors": [
      "Renata Camacho Bezerra (Universidade Estadual do Oeste do Paraná)",
      "Richael Silva Caetano (Universidade Estadual do Oeste do Paraná)"
    ],
    "abstract": "Esta pesquisa qualitativa, do tipo estudo de caso, cuja análise foi interpretativa, tem como objetivo apresentar uma adaptação do Lesson Study para a disciplina de Estágio Supervisionado e visa responder a seguinte indagação: “Como uma adaptação do Lesson Study, realizada na disciplina de Estágio Supervisionado, pode contribuir com a gradativa constituição da identidade profissional do professor de Matemática?”. Para a produção dos dados, utilizamos: observação participante, trabalho narrativo e questionário. Os resultados apontaram que a reflexão e a colaboração realizadas no/com o grupo, para a elaboração e execução de um plano de aula, por meio dessa adaptação do Lesson Study, foram importantes e permitiram, ao futuro professor de Matemática, no âmbito individual, a constituição gradativa da identidade profissional.",
