    "id": "IXSIPEM-2024-GT10-0255",
    "title": "A Matemática na Modelagem Matemática na Educação Matemática: algumas compreensões",
    "authors": [
      "Rosangela Ramon (Instituto Federal de Santa Catarina)",
      "Tiago Emanuel Klüber (Universidade Estadual do Oeste do Paraná)"
    ],
    "abstract": "Nesse texto, detemo-nos a apresentar parte dos resultados da pesquisa de doutorado que investigou a Matemática na Modelagem Matemática na Educação Matemática. Para a pesquisa assumimos uma visão fenomenológica de conhecimento, que tem como uma de suas características a suspensão de crenças, teorias e expectativas em relação ao investigado. A interrogação que orientou esta pesquisa foi: O que é isto, a Matemática na Modelagem Matemática na Educação Matemática? Neste texto, apresentamos resultados dessa pesquisa, tais como, o entendimento de que a Matemática é a aplicação da Matemática, a Matemática da Modelagem não tem certo ou errado, é uma Matemática mais flexível e pode ser menos rigorosa do que em outros contextos.",
