    "id": "IXSIPEM-2024-GT11-0462",
    "title": "Sobre os usos das palavras em títulos e ementas de disciplinas que envolvem matemática em cursos de Pedagogia",
    "authors": [
      "Rejane Siqueira Julio (Universidade Federal de Alfenas)"
    ],
    "abstract": "Estudos sobre disciplinas que envolvem matemática em cursos de Pedagogia têm sido realizados no âmbito da formação de professores que ensinam matemática. Neste texto, é feita uma discussão filosófica que se direciona a abordar os diferentes usos que podem ser feitos de palavras e termos presentes em títulos e ementas dessas disciplinas, utilizando dados de uma pesquisa documental, a inspiração em alguns escritos do filósofo Ludwig Wittgenstein e alguns pressupostos do Modelo dos Campos Semânticos. Apontamos a impossibilidade e não necessidade de estabelecimento de essências do que essas disciplinas são, mas que a existência de diferentes modos de produção de significados, ainda que exista, possa possibilitar um cuidado maior na escrita dessas disciplinas.",
