    "abstract": "Este estudo investiga os potenciais impactos e implicações que a utilização de informações provenientes do Instituto Brasileiro de Geografia e Estatística (IBGE) pode ter na aprendizagem dos estudantes. A metodologia adotada foi a pesquisa participante realizada em uma escola pública no estado do Ceará, Brasil, envolvendo 10 estudantes. Os resultados revelam que, ao explorar os dados de forma dialética, estudantes apoiam-se na Estatística como ferramenta para compreender, analisar e refletir sobre questões estruturais da sociedade, além de identificar e propor formas de engajamento ativo nessas questões.",
