    "id": "IXSIPEM-2024-GT12-0530",
    "title": "Brincadeiras e Letramento Estatístico: Quais são as potencialidades do brincar quanto ao Letramento Estatístico?",
    "authors": [
      "Pedro Henrique Barcarolo (Universidade de São Paulo)",
      "Raquel Milani (Universidade de São Paulo)"
    ],
    "abstract": "Este artigo é um recorte de uma Dissertação de Mestrado em Educação. Tem como objetivo analisar, com alunos do sétimo ano do Ensino Fundamental, a potencialidade de brincadeiras promoverem o Letramento Estatístico. Para isso, como aporte teórico, se embasa no Letramento Estatístico, Educação Matemática Crítica, Cenários para Investigação e Brincadeiras. A pesquisa está caracterizada como qualitativa delimitada como investigação-ação. Os dados produzidos são apresentados e analisados através de uma adaptação de “Isolados”, por meio de episódio. Os resultados encontrados possibilitam afirmar as brincadeiras tem potencialidade de promoverem o Letramento Estatístico de forma lúdica. Também articula diversos aspectos importantes para uma Educação Matemática Crítica, com a promoção da materacia ao vivenciar os dados por meio do brincar.",
