    "title": "Investigação estatística na Educação Básica: possibilidades para o letramento estatístico",
    "authors": [
      "Ana Paula Gonçalves Pita (Universidade Metropolitana de Santos e Secretaria Municipal de Educação de São Vicente)",
      "Andrea Pavan Perin (Faculdade de Tecnologia do Estado de São Paulo)",
      "Celso Ribeiro Campos (Faculdade de Economia da Pontifícia Universidade Católica de São Paulo)"
    ],
    "abstract": "Essa pesquisa tem como objetivo apresentar situações que favoreceram reflexões sobre a importância da investigação estatística contribuindo para potencializar competências e habilidades dispostas na Base Nacional Comum Curricular. As propostas foram desenvolvidas em uma turma do 3º ano do ensino médio. Para tanto, apresentamos as possibilidades envolvendo letramento estatístico contribuindo para a práxis docente e viabilizando meios para educação estatística e reflexão crítica dos estudantes. As investigações se deram por meio das quatro etapas de investigação mencionadas no Guidelines for Assessment and Instruction in Statistics Education II. As propostas experienciada colaboraram com a reflexão docente sobre a importância dos estudantes realizarem investigação. O estudo foi de natureza qualitativa exploratório. Os estudantes desenvolveram postura de investigadores, pois a todo momento fizeram questionamentos colaborando para o pensar estatisticamente para a tomada de decisões, argumentações e validações.",
