    "title": "Cálculos mentais rápidos e sem erros: como meninas olímpicas definem pessoas \"boas em matemática\"",
    "authors": [
      "Débora Azevedo de Castro Borba (Universidade Federal do Rio de Janeiro)",
      "Agnaldo da Conceição Esquincalha (Universidade Federal do Rio de Janeiro)"
    ],
    "abstract": "Estereótipos que associam a lógica e a razão como ditas masculinas e a sensibilidade e o cuidado como ditos femininos são enraizados na sociedade e podem influenciar na baixa presença de mulheres nas áreas das ciências ditas exatas. Para entender melhor isso, esse artigo tem como foco investigar o que meninas medalhistas em uma olimpíada de matemática acreditam que caracteriza uma pessoa “boa em matemática”, a partir de suas respostas a um formulário eletrônico enviado por e-mail. Como resultados iniciais, foi observado o enaltecimento de cálculos mentais e rapidez ao aprender e efetuar contas como características que destacam quem tem habilidades matemáticas bem desenvolvidas. Além disso, algumas meninas apontaram como característica desse destaque a ausência do erro ou o conhecimento absoluto da área.",
