    "abstract": "Este artigo tem como objetivo investigar as concepções de uma intérprete educacional sobre sua atuação na tradução intepretação de situações do campo aditivo. A pesquisa é de abordagem qualitativa, e como referencial teórico foi utilizada a Teoria dos Campos Conceituais. Participou do estudo uma intérprete educacional da Língua Brasileira de Sinais (Libras) de uma escola pública. Foram utilizadas como técnicas de produção de dados entrevista semiestruturada e filmagem. Os dados foram analisados utilizando o diálogo como método de conversação para a busca de novas percepções sobre o tema. A análise da forma como a intérprete concebe a sua prática e suas escolhas tradutórias pode contribuir para ampliar as possibilidades de compreensão de enunciados na língua-alvo por estudantes surdos.",
