    "title": "Desvendando Barreiras: A Interseccionalidade e a Inclusão de Mulheres com Corpos Dissidentes na Matemática",
    "authors": [
      "Jéssica Maria Oliveira de Luna (Secretaria Municipal de Educação de Duque de Caxias)"
    ],
    "abstract": "Este estudo investigou a aplicação da interseccionalidade na Educação Matemática, explorando as experiências das licenciandas em Matemática Lueji e Luma. O objetivo incluiu analisar de forma abrangente as disparidades persistentes que mulheres com corpos dissidentes enfrentam ao buscar inclusão nos ambientes de ensino-aprendizagem de Matemática. A abordagem metodológica foi qualitativa, utilizando entrevistas para coletar dados sobre as vivências das participantes a fim de construir narrativas. Fundamentado na teoria Interseccional, o estudo revelou como identidades múltiplas afetam profundamente as jornadas educacionais de Lueji e Luma. Os resultados destacam a necessidade urgente de currículos mais inclusivos e práticas pedagógicas no ensino de Matemática que sejam sensíveis à diversidade.",
