    "id": "IXSIPEM-2024-GT13-0470",
    "title": "Diálogos sobre o capacitismo na formação de professores: articulações na rede municipal de ensino de Votuporanga (SP)",
    "authors": [
      "Ana Lúcia Manrique (Pontifícia Universidade Católica)",
      "Elton de Andrade Viana (Pontifícia Universidade Católica)"
    ],
    "abstract": "Com o objetivo de identificar elementos pertinentes para uma formação de professores que ensinam matemática com uma perspectiva inclusiva, apresenta-se uma pesquisa qualitativa metodologicamente referenciada na epistemologia da práxis que fundamenta as recentes discussões sobre a formação continuada de professores. A pesquisa ocorreu no âmbito de um programa de formação continuada de professores de educação básica na cidade de Votuporanga, São Paulo. Analisa os dados produzidos durante a realização de uma das tarefas desse programa de formação, identificando quatro elementos: (1) a necessidade de abordarmos o capacitismo na formação de professores, (2) a superação de práticas direcionadas por descritores médicos, (3) a urgência de uma revisão do vocabulário pedagógico e (4) a introdução de uma discussão pautada na interseccionalidade.",
