    "id": "IXSIPEM-2024-GT14-0521",
    "title": "Avaliação escolar em Matemática: um estudo à luz da Teoria Antropológica do Didático",
    "authors": [
      "Marcela Silva de Albuquerque (Universidade Federal Rural de Pernambuco)",
      "Simone Maria Chalub Bandeira Bezerra (Universidade Federal do Acre)",
      "Elisângela Bastos de Melo Espíndola (Universidade Federal Rural de Pernambuco)"
    ],
    "abstract": "Este artigo é fruto de uma tese em andamento e tem como objetivo analisar a avaliação escolar em Matemática à luz da Teoria Antropológica do Didático. A metodologia da pesquisa foi organizada em duas etapas. Na primeira etapa, realizamos a análise de documentos da Educação Brasileira, da Rede de Ensino Estadual de Pernambuco e do Projeto Político Pedagógico de uma escola. Na segunda etapa, aplicamos uma entrevista com uma professora de Matemática. Os resultados apontam indícios da influência dos níveis Sociedade, Escola e Pedagogia, sobre as práticas de avaliação dessa professora no nível Disciplina. Por exemplo, na composição da média bimestral de Matemática que deve acontecer por meio de até cinco atividades avaliativas além de uma prova, dentre outras condições.",
