    "title": "O ensino de Matemática no Colégio São José das Irmãs Franciscanas, de São Leopoldo/RS: identificando fontes primárias de pesquisa",
    "authors": [
      "Malcus Cassiano Kuhn (Instituto Federal Sul-rio-grandense)",
      "Silvio Luiz Martins Britto (Faculdades Integradas de Taquara)"
    ],
    "abstract": "O artigo apresenta fontes primárias de pesquisa com vestígios sobre o ensino de Matemática no Colégio São José das Irmãs Franciscanas, de São Leopoldo, Rio Grande do Sul, no final do século XIX e na primeira metade do século XX. Como o tema se insere na História da Educação Matemática, este estudo qualitativo e documental ampara-se em referenciais sobre manuais didáticos e cadernos escolares como fontes de pesquisa. Foram identificados sete livros de Aritmética, produzidos pelas Irmãs Franciscanas para o público feminino de seus Colégios, além de dois cadernos de contas, datados de 1905, e de uma ex-aluna do Colégio São José. Esses materiais possibilitam tecer um enredo sobre o ensino de Matemática no Colégio São José no período considerado.",
