    "id": "IXSIPEM-2024-GT15-0351",
    "title": "Ocupar a História da Educação Matemática: temas e questões no contexto da Educação do Campo",
    "authors": [
      "Filipe Santos Fernandes (Universidade Federal de Minas Gerais)"
    ],
    "abstract": "A inserção e a consolidação no espaço universitário de demandas legítimas provenientes de grupos ligados à luta contra a violação do direito à terra têm convocado à reflexão sobre processos históricos e educacionais que mantiveram indivíduos e coletivos do campo subalternizados ou silenciados. Não diferente, a Educação Matemática tem aprofundado o seu diálogo com os povos do campo, buscando compartilhar projetos políticos e educacionais de forma atenta à história e às pautas da luta camponesa. É nesse cenário que se objetiva, neste texto, discutir temáticas que nascem do encontro entre a História da Educação Matemática e a Educação do Campo, na emergência de questões, cenários, fontes, fundamentações e possibilidades teórico-analíticas para uma historiografia da Educação Matemática no Brasil.",
