    "id": "IXSIPEM-2024-GT16-0396",
    "title": "Contextualização em Matemática na Educação de Jovens, Adultos e Idosos – análises e propostas",
    "authors": [
      "Luciana Prado Mouta Pena (Universidade Federal Fluminense)"
    ],
    "abstract": "O presente artigo apresenta recorte de pesquisa qualitativa do tipo exploratória envolvendo a análise de literatura sobre o tema contextualização nas atividades curriculares na Educação de Jovens, Adultos e Idosos. Iniciamos apresentando noções conceituais de contextualização, destacando suas contribuições para o processo de ensino e de aprendizagem de matemática na EJA para, em seguida, destacarmos a importância de propostas moldadas em perspectivas de contextualização nesta modalidade. Exemplificamos um curso de formação de professores de matemática aplicado a docentes do Estado do Rio de Janeiro que teve a contextualização de atividades na EJA como um de seus motes, e que gerou impactos positivos em avaliações realizada em larga escala.",
