    "abstract": "Neste texto trazemos um recorte de nossa pesquisa desenvolvida durante o curso de Mestreado em Educação no Programa de Pós-Graduação em Educação da Universidade Federal Fluminense. Aqui buscamos responder à questão: Como se deu o percurso da EJA no âmbito da rede municipal de Macaé e sua história ao longo de 16 anos, da implementação às tentativas de desmonte, a resistência da comunidade escolar, a luta pela manutenção da EJA e do direito à educação? Utilizamos como metodologia a narrativa autobiográfica de um dos autores que vivenciou este processo como professor de artes do Colégio Municipal Pedro Adami. Além da legislação em vigor, utilizamos autores que tratam da EJA ou fazem uma análise conjuntural, como Saviane, Fávero, entre outros.",
