    "abstract": "Este texto contém discussões de uma tese defendida em 2023, cujo objetivo foi analisar interfaces entre currículos de matemática e processos de produção de subjetividades na EJA. Para isso, discursos sobre EJA foram estudados com base em referenciais teóricos metológicos como os provenientes das narrativas de si (Bragança, 2008) e da cartografia (Rolnik, 1989). Os percursos construídos possibilitaram conjecturar que a precarização imposta à EJA também serviu para distrair a atenção de defensores de uma educação mais igualitária, para quaisquer brasileiros, do aprofundamento do projeto mercadológico de escolarização periférica e colonialista em curso, que atinge inclusive os sujeitos do ensino regular público, vide a manutenção de classes públicas de aceleração e a crescente juvenilização da EJA.",
