    "id": "IXSIPEM-2024-GT16-0256",
    "title": "Perspectivas teórico-metodológicas para focalizar pessoas jovens e adultas surdas num curso de Educação Financeira ministrado em Libras",
    "authors": [
      "Rodrigo Carlos Pinheiro (Universidade Federal de Ouro Preto)",
      "Maria da Conceição Ferreira Reis Fonseca (Universidade Federal de Minas Gerais)"
    ],
    "abstract": "Neste artigo, discutimos motivações técnicas e implicações político-pedagógicas das escolhas teórico-metodológicas da investigação que focalizou pessoas jovens e adultas surdas apropriando-se de práticas de numeramento da Educação Financeira, em um curso online, ministrado em Libras por um professor surdo. O material empírico, produzido por observação participante, foi registrado na videogravação das aulas, cujas interações foram traduzidas e transcritas em português e em glosas. Procuramos justificar a adoção da Análise Social do Discurso, conforme proposta por Norman Fairclough, como perspectiva teórico-metodológica apontando como o estudo das dimensões textual, de prática social e de prática discursiva das interações resulta numa compreensão de tais estudantes jovens e adultas/os surdas/os bilíngues como sujeitos sociais de conhecimento e aprendizagem.",
