    "id": "IXSIPEM-2024-GT16-0466",
    "title": "Um estudo sobre o reconhecimento de experiências matemáticas de adultos no CIEJA Campo Limpo",
    "authors": [
      "Carla Cristina Pompeu (Universidade Federal do Triângulo Mineiro)",
      "Vinício de Macedo Santos (Universidade de São Paulo)"
    ],
    "abstract": "O presente artigo compreende um estudo qualitativo a partir da investigação sobre o reconhecimento de experiências matemáticas de jovens e adultos, por meio de entrevistas com gestor e professores, no Centro Integrado de Educação de Jovens e Adultos (CIEJA Campo Limpo) da cidade de São Paulo. Está fundamentado em teorias que tratam do valor social da matemática, das relações entre sujeito e conhecimento matemático, levando em conta o sujeito social, suas especificidades e contribuições no processo de aprendizagem. Com o objetivo de analisar o reconhecimento dos saberes matemáticos experienciais, a investigação proposta evidenciou que embora a Educação de Jovens e Adultos têm sido secundarizada nas políticas públicas nacionais, existem propostas educativas como no CIEJA Campo Limpo que reconhecem os saberes matemáticos experienciais dos sujeitos e os valorizam no processo educativo.",
